# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Reservation conflicted prepare retried through reservation_post" do
  include_context "timekeeping entry writes"

  it "reservation_post retries a conflicted prepare with the same operation id after nothing persisted" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    free_a = timekeeping_arrange.entry(company:, user:, project:)
    free_b = timekeeping_arrange.entry(company:, user:, project:)
    held = timekeeping_arrange.reserved_entry(company:, invoice_id: 777, state: "committed")
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    operation_id = SecureRandom.uuid
    body = { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active" }
    before = reservation_row_counts

    refused = reservation_post("prepare", company:, credential: service, body: body.merge("entries" => [free_a, held, free_b]))

    expect([refused.status, refused.parsed_body]).to eq(
      [409, { "reason" => "conflict", "conflicts" => [{ "entry_id" => held, "reason" => "on_another_invoice" }] }]
    )
    expect(reservation_row_counts).to eq(before)
    expect(Reservation.where(entry_id: held).pluck(:invoice_id, :state)).to eq([[777, "committed"]])

    retried = reservation_post("prepare", company:, credential: service, body: body.merge("entries" => [free_a, free_b]))

    expect([retried.status, retried.parsed_body]).to eq(
      [200, { "operation_id" => operation_id, "state" => "prepared",
              "entries" => [{ "entry_id" => free_a, "company_id" => company }, { "entry_id" => free_b, "company_id" => company }] }]
    )
    expect(Reservation.where(entry_id: [free_a, free_b]).pluck(:invoice_id, :state)).to eq([[501, "provisional"], [501, "provisional"]])
  end
end

RSpec.describe "Reservation prepare outbox failure through reservation_post" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  it "reservation_row_counts is unchanged when the outbox insert fails and the retry runs as a first attempt" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    entry = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    body = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active", "entries" => [entry] }
    before = reservation_row_counts
    expect(before.keys).to eq(%i[reservations operations audit_events outbox_snapshots receipts versions])

    allow(OutboxSnapshot).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "outbox down")
    failed = begin
      reservation_post("prepare", company:, credential: service, body:)
    rescue ActiveRecord::StatementInvalid
      nil
    end

    expect(failed&.status).not_to eq(200)
    expect(reservation_row_counts).to eq(before)
    expect(timekeeping_arrange.entry_locked(entry)).to be(false)

    allow(OutboxSnapshot).to receive(:insert_all!).and_call_original
    retried = reservation_post("prepare", company:, credential: service, body:)

    expect([retried.status, retried.parsed_body.fetch("state")]).to eq([200, "prepared"])
    expect(OutboxSnapshot.where(id: entry).count).to eq(1)
    expect(reservation_row_counts.values_at(:reservations, :operations, :outbox_snapshots))
      .to eq([before[:reservations] + 1, before[:operations] + 1, before[:outbox_snapshots] + 1])
  end
end

RSpec.describe "Reservation replay after commit through reservation_post" do
  include_context "timekeeping entry writes"

  # "A replay after a terminal state changes nothing."
  it "answers a replayed commit, a late abort and a late prepare after commit without changing any row" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    entry = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    finish_body = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid }
    prepare_body = finish_body.merge("disposition" => "active", "entries" => [entry])

    expect(reservation_post("prepare", company:, credential: service, body: prepare_body).status).to eq(200)
    first_commit = reservation_post("commit", company:, credential: service, body: finish_body)
    expect([first_commit.status, first_commit.parsed_body]).to eq([200, { "reserved" => 1, "released" => 0 }])
    first_commit_body = first_commit.parsed_body
    # A replay may record its own service receipt, so receipts are left out of the comparison.
    after_commit = reservation_row_counts.except(:receipts)
    committed_after_commit = Reservation.where(state: "committed").count

    replayed_commit = reservation_post("commit", company:, credential: service, body: finish_body)
    expect([replayed_commit.status, replayed_commit.parsed_body]).to eq([200, first_commit_body])
    late_abort = reservation_post("abort", company:, credential: service, body: finish_body)
    expect([late_abort.status, late_abort.parsed_body]).to eq([200, { "dropped" => 0 }])
    late_prepare = reservation_post("prepare", company:, credential: service, body: prepare_body)
    expect([late_prepare.status, late_prepare.parsed_body.fetch("state")]).to eq([200, "committed"])

    expect(reservation_row_counts.except(:receipts)).to eq(after_commit)
    expect(Reservation.where(state: "committed").count).to eq(committed_after_commit)
    expect(timekeeping_arrange.reservations_for(entry)).to eq([{ "invoice_id" => 501, "state" => "committed" }])
    expect(timekeeping_arrange.entry_locked(entry)).to be(true)
  end
end
